#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using i128 = __int128_t;

const int MOD = 998244353;

string to_string(i128 x) {
    if (x == 0) return "0";
    string s;
    bool neg = x < 0;
    if (neg) x = -x;
    while (x > 0) {
        s += '0' + (x % 10);
        x /= 10;
    }
    if (neg) s += '-';
    reverse(s.begin(), s.end());
    return s;
}

void solve(vector<int>& vars, int base, i128& ans) {
    int n = vars.size();
    vector<int> left, right;

    function<void(int, int)> dfs = [&](int idx, int cur) {
        if (idx == n / 2) {
            left.push_back((cur + base) % MOD);
            return;
        }
        dfs(idx + 1, cur);
        dfs(idx + 1, (cur + vars[idx]) % MOD);
    };

    dfs(0, 0);

    function<void(int, int)> dfs2 = [&](int idx, int cur) {
        if (idx == n) {
            right.push_back(cur);
            return;
        }
        dfs2(idx + 1, cur);
        dfs2(idx + 1, (cur + vars[idx]) % MOD);
    };

    dfs2(n / 2, 0);

    sort(left.begin(), left.end());
    sort(right.begin(), right.end());

    ll sumR = accumulate(right.begin(), right.end(), 0LL) % MOD;
    int j = right.size() - 1;

    for (int a : left) {
        while (j >= 0 && a + right[j] >= MOD) --j;
        ans += (ll)a * right.size() + sumR - (ll)(right.size() - 1 - j) * MOD;
    }
}

ll pw10[17];

ll count_prefix(const string& s, ll n, const string& ns) {
    ll val = 0;
    for (char c : s) val = val * 10 + (c - '0');

    ll cnt = 0;
    int slen = s.size();
    int nlen = ns.size();

    for (int len = slen; len <= nlen; ++len) {
        if (len < nlen) {
            cnt += pw10[len - slen];
        } else {
            if (s < ns) {
                cnt += pw10[len - slen];
            } else if (s == ns) {
                cnt += n - val * pw10[nlen - slen] + 1;
            }
        }
    }
    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    cin >> n;

    string ns;
    if (n == 0) ns = "0";
    else {
        ll t = n;
        while (t) {
            ns += '0' + (t % 10);
            t /= 10;
        }
        reverse(ns.begin(), ns.end());
    }

    pw10[0] = 1;
    for (int i = 1; i < 17; ++i) pw10[i] = pw10[i-1] * 10;

    i128 total = 0;

    for (int len = 1; len <= (int)ns.size(); ++len) {
        for (int first_diff = 0; first_diff < min(len, (int)ns.size()); ++first_diff) {
            string prefix;
            ll cur_val = 0;

            for (int i = 0; i < first_diff; ++i) {
                prefix += ns[i];
                cur_val = cur_val * 10 + (ns[i] - '0');
            }

            for (int last = 0; last <= 9; ++last) {
                if (first_diff == 0 && last == 0) continue;
                if (first_diff < (int)ns.size() && last == ns[first_diff] - '0') continue;
                if (len == (int)ns.size() && last > ns[first_diff] - '0') continue;

                string curp = prefix + char('0' + last);
                ll curv = cur_val * 10 + last;

                ll base = 0;
                string tmp;

                for (int i = 0; i < (int)curp.size(); ++i) {
                    char start = (i == 0) ? '1' : '0';
                    for (char d = start; d < curp[i]; ++d) {
                        base += count_prefix(tmp + d, n, ns);
                    }
                    tmp += curp[i];
                }
                base += (int)curp.size() - 1;

                vector<int> vars;
                tmp = curp;
                for (int i = curp.size(); i < len; ++i) {
                    int cnt = count_prefix(tmp + '0', n, ns) % MOD;
                    vars.push_back(cnt);
                    tmp += '0';
                }

                base += 1;
                base -= curv * pw10[len - curp.size()];

                for (int i = 0; i < (int)vars.size(); ++i) {
                    vars[(int)vars.size() - 1 - i] -= pw10[i] % MOD;
                }

                int b = base % MOD;
                if (b < 0) b += MOD;

                for (int& v : vars) {
                    v %= MOD;
                    if (v < 0) v += MOD;
                }

                solve(vars, b, total);
            }
        }
    }

    // Handle numbers that are prefixes of n
    string cur;
    ll val = 0;
    for (int len = 1; len <= (int)ns.size(); ++len) {
        cur += ns[len-1];
        val = val * 10 + (ns[len-1] - '0');

        ll cnt = 1;
        string tmp;
        for (int i = 0; i < (int)cur.size(); ++i) {
            char start = (i == 0) ? '1' : '0';
            for (char d = start; d < cur[i]; ++d) {
                cnt += count_prefix(tmp + d, n, ns);
            }
            tmp += cur[i];
        }
        cnt += (int)cur.size() - 1;
        cnt -= val;
        cnt %= MOD;
        if (cnt < 0) cnt += MOD;

        total += cnt;
    }

    total %= (1000000007LL);
    cout << to_string(total) << "\n";

    return 0;
}
